// Loaded in the <head> of every demo page (public/demos/<package>/<slug>.html), generated by tools/bin/demos.
//
// - Theme: follows the Starlight theme of the embedding page (`data-theme` on its root element) through Bootstrap's
//   `data-bs-theme`, or the system preference when the page is opened on its own.
// - Height: sizes the embedding <iframe> to the content, including open menus, popovers and dialogs, so the frame
//   never scrolls.
// - Navigation: links and forms of the examples point to routes of a Yii application that does not exist here, so
//   the default action of link clicks and form submissions is cancelled (after Bootstrap's own handlers ran).
(() => {
  'use strict';

  const root = document.documentElement;
  const scheme = window.matchMedia('(prefers-color-scheme: dark)');
  let host = null;

  try {
    host = window.frameElement ? window.parent.document.documentElement : null;
  } catch {
    host = null;
  }

  // `only light`: browsers that force dark mode on web pages would otherwise darken the light theme too (the site
  // declares the same in src/styles/theme.css).
  const applyTheme = () => {
    const theme = host?.dataset.theme;
    const resolved = theme === 'dark' || theme === 'light' ? theme : (scheme.matches ? 'dark' : 'light');

    root.dataset.bsTheme = resolved;
    root.style.colorScheme = resolved === 'light' ? 'only light' : 'dark';
  };

  applyTheme();

  if (host) {
    new MutationObserver(applyTheme).observe(host, { attributes: true, attributeFilter: ['data-theme'] });
  } else {
    scheme.addEventListener('change', applyTheme);
  }

  window.addEventListener('click', (event) => {
    if (event.target instanceof Element && event.target.closest('a[href]')) {
      event.preventDefault();
    }
  });
  window.addEventListener('submit', (event) => event.preventDefault());

  // Overlays (dialogs, drawers) fill the frame, so their share of the height is capped to keep the size stable.
  const OVERLAY_MAX = 560;
  const GAP = 16;
  let scheduled = 0;

  const measure = () => {
    scheduled = 0;

    const frame = window.frameElement;
    const main = document.getElementById('demo');

    if (!frame || !main || window.innerWidth === 0) {
      return;
    }

    const body = getComputedStyle(document.body);
    const contentBottom = main.getBoundingClientRect().bottom + window.scrollY;
    let height = contentBottom + parseFloat(body.paddingBottom || '0');

    for (const element of document.body.querySelectorAll('*')) {
      const style = getComputedStyle(element);

      if ((style.position !== 'absolute' && style.position !== 'fixed') || style.visibility === 'hidden'
        || element.getClientRects().length === 0) {
        continue;
      }

      const rect = element.getBoundingClientRect();

      if (style.position === 'fixed') {
        const content = [...element.children].reduce((sum, child) => sum + child.getBoundingClientRect().height, 0)
          + parseFloat(style.paddingTop || '0') + parseFloat(style.paddingBottom || '0');

        height = Math.max(height, Math.min(OVERLAY_MAX, Math.max(content, 1) + 4 * GAP));
      } else if (rect.top < 0) {
        height = Math.max(height, contentBottom + rect.height + GAP);
      } else if (rect.bottom + window.scrollY > contentBottom) {
        height = Math.max(height, rect.bottom + window.scrollY + GAP);
      }
    }

    const value = `${Math.ceil(height)}px`;

    if (frame.style.height !== value) {
      frame.style.height = value;
    }
  };

  const schedule = () => {
    scheduled ||= window.requestAnimationFrame(measure);
  };

  document.addEventListener('DOMContentLoaded', () => {
    const resize = new ResizeObserver(schedule);

    resize.observe(document.body);
    resize.observe(document.getElementById('demo') ?? document.body);
    new MutationObserver(schedule).observe(document.body, { attributes: true, childList: true, subtree: true });

    for (const type of ['toggle', 'transitionend', 'animationend', 'close']) {
      document.addEventListener(type, schedule, true);
    }

    window.addEventListener('load', schedule);
    window.addEventListener('resize', schedule);
    schedule();
  });
})();
